import{_ as i,o as u,c as n,a2 as o}from"./chunks/framework.CqpfiAoK.js";const r=JSON.parse('{"title":"Mchakato wa Kufungua na Kushiriki Teknolojia","description":"","frontmatter":{},"headers":[],"relativePath":"sw/69-技术开放与共享机制.md","filePath":"sw/69-技术开放与共享机制.md","lastUpdated":1789183869000}'),k={name:"sw/69-技术开放与共享机制.md"};function t(e,a,l,w,h,m){return u(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="mchakato-wa-kufungua-na-kushiriki-teknolojia" tabindex="-1">Mchakato wa Kufungua na Kushiriki Teknolojia <a class="header-anchor" href="#mchakato-wa-kufungua-na-kushiriki-teknolojia" aria-label="Permalink to &quot;Mchakato wa Kufungua na Kushiriki Teknolojia&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>69</td></tr><tr><td>Moduli</td><td>Mfumo wa Teknolojia na Nishati</td></tr><tr><td>Maneno Muhimu ya Msingi</td><td>Kufungua teknolojia, kushiriki maarifa, sheria za chanzo wazi, kueneza teknolojia, kuzuia ushirikiano</td></tr></tbody></table><h2 id="_1-dhana-ya-msingi-ya-kufungua-teknolojia" tabindex="-1">1. Dhana ya Msingi ya Kufungua Teknolojia <a class="header-anchor" href="#_1-dhana-ya-msingi-ya-kufungua-teknolojia" aria-label="Permalink to &quot;1. Dhana ya Msingi ya Kufungua Teknolojia&quot;">​</a></h2><p>Mchakato wa kufungua na kushiriki teknolojia wa ustaarabu wa ushirika wa nanga ni uundeshaji wa kanuni ya msingi ya &quot;kazi nyingi mapato mengi, kukua kwa yenyewe, kila mtu ana njia, maendeleo ya pamoja ya kila rangi&quot; katika uwanja wa teknolojia. Dhana yake ya msingi ni: maarifa ya teknolojia, kama bidhaa ya mageuzi ya pamoja ya ustaarabu wote, yanapaswa kushirikiwa na ustaarabu wote; ushirikiano wa teknolojia na kizuizi cha maarifa ni mabaki ya mfumo wa wachambaji katika uwanja wa teknolojia, na yanapaswa kuondolewa kupitia muundo wa taasisi.</p><p>Kufungua teknolojia hakumaanishi kukataa mchango wa watafiti wa teknolojia. Kinyume chake, ustaarabu wa ushirika umeanzisha mchakato wa motisha wa teknolojia wa &quot;mchango unaopimika, faida inayofuatilia&quot;, kuhakikisha kwamba kazi ya watafiti inapata malipo yenye usawazishaji, wakati huo huo matokeo ya teknolojia yanaweza kuleta manufaa kwa viumbe vyote kwa kiwango cha chini cha zaidi. Kiini cha mchakato huu ni kubadilisha teknolojia kutoka &quot;bidhaa inayoshirikiana na watu wachache&quot; hadi &quot;miundombinu inayoshirikiwa na ustaarabu wote&quot;.</p><h2 id="_2-mfumo-wa-kufungua-kwa-viwango-vya-teknolojia" tabindex="-1">2. Mfumo wa Kufungua kwa Viwango vya Teknolojia <a class="header-anchor" href="#_2-mfumo-wa-kufungua-kwa-viwango-vya-teknolojia" aria-label="Permalink to &quot;2. Mfumo wa Kufungua kwa Viwango vya Teknolojia&quot;">​</a></h2><p>Kufungua teknolojia kunatekelezaji kufungua kwa viwango kulingana na kiwango cha hatari na ukomavu:</p><table tabindex="0"><thead><tr><th>Kiwango cha Kufungua</th><th>Teknolojia Inayotumika</th><th>Njia ya Kufungua</th><th>Masharti ya Ufikiaji</th></tr></thead><tbody><tr><td>Kufungua Kabisa</td><td>Teknolojia zilizokomaa za kiwango R0, R1</td><td>Nyaraka zote za teknolojia na michoro ya ubunishaji inachapishwa bure</td><td>Hakuna kizuizi, kila kiumbe kinaweza kupata</td></tr><tr><td>Kufungua kwa Idhini</td><td>Teknolojia zilizokomaa za kiwango R2</td><td>Kanuni za msingi zinachapishwa, utekelezaji wa uhandisi unahitaji ombi la leseni</td><td>Lazima kupitia mafunzo ya msingi ya usalama, na kuahidi kufuata viwango vya matumizi</td></tr><tr><td>Kufungua Mdogo</td><td>Teknolojia za kiwango R3</td><td>Inafunguliwa kwa taasisi za utafiti zilizoitwa tu, inahitaji usaini wa mkataba wa usalama</td><td>Lazima kuwa na nafasi iliyotengwa ya kiwango S na uwezo wa ukaguzi wa maadili</td></tr><tr><td>Kufungua Kukatazwa</td><td>Teknolojia zilizokatazwa za kiwango R4</td><td>Haifungui</td><td>Katazwa kabisa</td></tr></tbody></table><p>Kwa teknolojia zilizofunguliwa kabisa, ustaarabu wa ushirika umeanzisha &quot;Maktaba ya Sheria za Chanzo Wazi&quot; — hifadhi ya maarifa ya teknolojia inayofanana na jumuiya za programu za chanzo wazi katika ulimwengu halisi. Watafiti wote wanaweza kuwasilisha matokeo yao ya teknolojia kwenye Maktaba ya Sheria za Chanzo Wazi, ambayo baada ya ukaguzi wa kamati ya teknolojia, inafunguliwa kwa ustaarabu wote. Teknolojia ndani ya Maktaba ya Sheria za Chanzo Wazi zinachukua &quot;Leseni ya Kushiriki ya Ushirika&quot;, inaruhusu matumizi ya bure, marekebisho, na usambazaji wa tena, lakini kazi zilizotokana pia zinapaswa kushirikiwa kwa njia ile ile ya chanzo wazi.</p><h2 id="_3-miundombinu-ya-kueneza-teknolojia" tabindex="-1">3. Miundombinu ya Kueneza Teknolojia <a class="header-anchor" href="#_3-miundombinu-ya-kueneza-teknolojia" aria-label="Permalink to &quot;3. Miundombinu ya Kueneza Teknolojia&quot;">​</a></h2><p>Ili kuhakikisha kwamba kufungua teknolojia hakufanyike kuwa tu fomu, ustaarabu wa ushirika umejenga miundombinu kamili ya kueneza teknolojia:</p><ol><li><strong>Mfumo wa Elimu ya Teknolojia</strong>: Katika mfumo wa elimu ya ushirika, maarifa ya msingi ya uhandisi wa sheria yameorodheshwa kama maudhui ya elimu ya jumla, kuhakikisha kwamba kila kiumbe kina uwezo wa kuelewa na kutumia teknolojia ya msingi. Elimu ya teknolojia ya juu inafunguliwa bure kwa wanafunzi wote walio tayari</li><li><strong>Mtandao wa Uenezi wa Teknolojia</strong>: Kutingama na mtandao wa mawasiliano kati ya viwango, umejengwa jukwaa la uenezi wa teknolojia la ulimwengu mzima, ikiwa ni pamoja na kozi za mtandaoni, manung&#39;a ya teknolojia, maabara ya virtual, n.k., kuruhusu wanafunzi katika viwango vya kando kupata maarifa ya teknolojia ya hivi karibuni</li><li><strong>Vifaa vya Teknolojia vya Umma</strong>: Katika nanga za jumuiya vinawekwa maabara ya teknolojia ya umma na vifaa vya utengenezaji, kila kiumbe kinaweza kuweka nafasi ya kutumia, na kubadilisha maarifa ya teknolojia kuwa bidhaa halisi</li><li><strong>Mfumo wa Mwalimu wa Teknolojia</strong>: Wataalamu wa teknolojia ya juu wana jukumu la kutoa huduma kama walimu wa teknolojia kwa mara ya kawaida, kuongoza wanafunzi wa awali, na jukumu hili linahesabiwa katika kiwango cha mchango wa ushirika wao</li></ol><h2 id="_4-kupimwa-na-kuchochezwa-kwa-mchango-wa-teknolojia" tabindex="-1">4. Kupimwa na Kuchochezwa kwa Mchango wa Teknolojia <a class="header-anchor" href="#_4-kupimwa-na-kuchochezwa-kwa-mchango-wa-teknolojia" aria-label="Permalink to &quot;4. Kupimwa na Kuchochezwa kwa Mchango wa Teknolojia&quot;">​</a></h2><p>Uendelevu wa mchakato wa kufungua teknolojia unategemea mfumo wa kupimwa na kuchochezwa kwa mchango unaofaa:</p><ul><li><strong>Kupimwa kwa Kiwango cha Mchango</strong>: Baada ya matokeo ya teknolojia yaliyotumwa na watafiti kuingizwa katika Maktaba ya Sheria za Chanzo Wazi, &quot;kiwango cha mchango wa teknolojia&quot; kinakadiriwa kulingana na thamani yake ya teknolojia, upeo wa matumizi, na mchango uliotokana. Kiwango cha mchango ni msingi muhimu wa mgawanyo wa rasilimali katika mchakato wa mkataba wa uzalishaji pamoja</li><li><strong>Haki ya Matumizi ya Kipaumbele</strong>: Watafiti wa teknolojia wanafurahia, kwa muda fulani, haki ya matumizi ya kipaumbele ya matokeo yao ya teknolojia na kipaumbele cha huduma ya juu, lakini hawawezi kushirikiana na haki ya uenezi wa teknolojia</li><li><strong>Mfumo wa Heshi</strong>: Watafiti wa teknolojia waliyotoa mchango muhimu kwa ustaarabu wote wanapewa heshi kama vile &quot;Nishani ya Teknolojia ya Ushirika&quot;, na mafanikio yao yanaandikishwa katika historia ya teknolojia ya ustaarabu</li><li><strong>Faida ya Kudumu</strong>: Kwa matumizi ya teknolojia ya juu inayotumia nisha nyingi, watafiti wanaweza kupata sehemu yenye usawazishaji kutoka kwa faida ya matumizi, lakini uwiano wa sehemu unafadhiwa na upeo wa juu wa sheria ya kuzuia ushirikiano</li></ul><h2 id="_5-kuzuia-ushirikiano-na-haki-ya-teknolojia" tabindex="-1">5. Kuzuia Ushirikiano na Haki ya Teknolojia <a class="header-anchor" href="#_5-kuzuia-ushirikiano-na-haki-ya-teknolojia" aria-label="Permalink to &quot;5. Kuzuia Ushirikiano na Haki ya Teknolojia&quot;">​</a></h2><p>Utekelezaji wa mchakato wa kufungua teknolojia unahakikishwa kwa mkali na sheria ya kuzuia ushirikiano:</p><ul><li>Inakatazwa kwa kila taasisi au mtu kushirikiana na haki ya uenezi wa teknolojia ya msingi kupitia kizuizi cha hati, siri ya teknolojia, n.k.</li><li>Inakatazwa tabia ya &quot;kufuli teknolojia&quot;, yaani kulazimisha watumiaji kutegemea watoa huduma wa teknolojia maalum kupitia kuunda kwa makosa viwango visivyoendana</li><li>Kwa teknolojia za aina ya miundombinu muhimu (kama vile vifaa vya nanga, mgawanyo wa nisha, mawasiliano kati ya viwango), inatekelezaji kufungua kwa kulazimisha, na viwango vya msingi vya teknolojia vinapaswa kuandaliwa kwa pamoja na ustaarabu wote</li><li>Kuanzisha mchakato wa tathmini ya haki ya teknolojia, kaguzi mara kwa mara kiwango cha usawa wa kueneza teknolojia, na kutoa msaada uliolengwa kwa viwango na vikundi vilivyochelewera teknolojia</li></ul><h2 id="_6-usawa-kati-ya-kufungua-teknolojia-na-usalama" tabindex="-1">6. Usawa kati ya Kufungua Teknolojia na Usalama <a class="header-anchor" href="#_6-usawa-kati-ya-kufungua-teknolojia-na-usalama" aria-label="Permalink to &quot;6. Usawa kati ya Kufungua Teknolojia na Usalama&quot;">​</a></h2><p>Inahitajika usawa wa busara kati ya kufungua teknolojia na usalama wa teknolojia. Njia ya ustaarabu wa ushirika ni:</p><ul><li>Kanuni za msingi na maarifa ya jumla zinafunguliwa kabisa, kuruhusu watu wengi zaidi kuelewa kiini cha teknolojia, na kwa hivyo kutambua vizuri hatari za teknolojia</li><li>Vigezo maalum vya operesheni zenye hatari kubwa na maelezo ya utekelezaji vinafunguliwa kwa mdogo, vinatolewa kwa taasisi zenye hali za usalama tu</li><li>Maarifa ya teknolojia zilizokatazwa yanahifadhiwa kwa siri kwa mkali, lakini uchambuzi wa maadili wa &quot;kwa nini imekatazwa&quot; unafunguliwa na uwazi, kuruhusu ustaarabu wote kuelewa maana ya uwepo wa mipaka</li><li>Kuanzisha viwango vya &quot;uenezi wa teknolojia wenye uwajibikaji&quot;, wauenezi wa teknolojia wana jukumu la kueneza kwa pamoja njia za matumizi salama na mipaka ya maadili ya teknolojia</li></ul><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Mchakato wa kufungua na kushiriki teknolojia ni mojawapo ya tabia muhimu zinazotofautisha ustaarabu wa ushirika wa nanga na ustaarabu wa wachambaji. Katika mfumo wa wachambaji, teknolojia ni zana ya wavuvi kuwakandamiza wanyonge; katika ustaarabu wa ushirika, teknolojia ni ngazi ya mageuzi ya pamoja ya kila rangi. Kupitia kufungua kwa viwango, kueneza miundombinu, kuchocheza kwa usawazishaji, na uhakikisho wa kuzuia ushirikiano, ustaarabu wa ushirika unajenga mfumo wa mazingira ya teknolojia ambapo &quot;maarifa yanayotiririka kwa uhuru, uwezo unaongezeka kwa jumla, mchango unalipwa kwa haki&quot;, ambayo inatoa nguvu ya ubunifu ya kudumu kwa kuinua mwelekeo wa jumla wa ustaarabu.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>60-Muhtasari wa Mfumo wa Teknolojia</li><li>68-Maadili ya Teknolojia na Mipaka ya Usalama</li><li>47-Sheria ya Kuzuia Ushirikiano</li></ul>',25)])])}const y=i(k,[["render",t]]);export{r as __pageData,y as default};
